<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Network Monitor PRO</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/variables.css?v=2"><link rel="stylesheet" href="../assets/css/common.css?v=2"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/dashboard.css?v=2"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body><?php require_once "../includes/sidebar.php"; ?><div class="main"><div class="topbar"><div><div class="page-title">Network Monitoring</div><div class="page-subtitle">Real-time MikroTik Ether1 traffic monitoring</div></div><button id="darkMode" class="btn btn-outline-secondary"><i class="bi bi-moon"></i></button></div><div class="row g-4"><div class="col-xl col-lg-4 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">Router Status</div><div class="stat-value" id="status">Checking...</div></div><div class="stat-icon icon-green"><i class="bi bi-wifi"></i></div></div></div></div><div class="col-xl col-lg-4 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">Download</div><div class="stat-value" id="download">0 Mbps</div></div><div class="stat-icon icon-blue"><i class="bi bi-arrow-down"></i></div></div></div></div><div class="col-xl col-lg-4 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">Upload</div><div class="stat-value" id="upload">0 Mbps</div></div><div class="stat-icon icon-green"><i class="bi bi-arrow-up"></i></div></div></div></div><div class="col-xl col-lg-4 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">CPU Load</div><div class="stat-value" id="cpu">0 %</div></div><div class="stat-icon icon-red"><i class="bi bi-cpu"></i></div></div></div></div><div class="col-xl col-lg-4 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">Active Alarm</div><div class="stat-value" id="activeAlarm">0</div></div><div class="stat-icon icon-red"><i class="bi bi-exclamation-triangle"></i></div></div></div></div></div><div class="row g-4 mt-1"><div class="col-xl-3 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">Memory Usage</div><div class="stat-value" id="memory">0 %</div></div><div class="stat-icon icon-gray"><i class="bi bi-memory"></i></div></div></div></div><div class="col-xl-3 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">Disk Usage</div><div class="stat-value" id="disk">0 %</div></div><div class="stat-icon icon-gray"><i class="bi bi-device-hdd"></i></div></div></div></div><div class="col-xl-3 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">RX Packet</div><div class="stat-value" id="rxPacket">0 pkt/s</div></div><div class="stat-icon icon-blue"><i class="bi bi-box-arrow-in-down"></i></div></div></div></div><div class="col-xl-3 col-md-6"><div class="monitor-card stat-card"><div class="d-flex justify-content-between"><div><div class="stat-title mt-0">TX Packet</div><div class="stat-value" id="txPacket">0 pkt/s</div></div><div class="stat-icon icon-green"><i class="bi bi-box-arrow-up"></i></div></div></div></div></div><div class="monitor-card chart-card mt-4"><div class="chart-header"><div><div class="chart-title">Traffic Ether1</div><div class="chart-subtitle">Real-time bandwidth monitoring</div></div><div><span class="badge bg-primary"><i class="bi bi-circle-fill"></i> LIVE</span></div></div><div class="chart-container"><canvas id="trafficChart"></canvas></div></div><div class="row g-4 mt-1"><div class="col-lg-4"><div class="monitor-card p-4"><h6 class="mb-4"><i class="bi bi-speedometer2"></i> Traffic Statistics</h6><div class="row"><div class="col-6"><div class="peak-label">Peak Download</div><div class="peak-value text-primary" id="peakDownload">0 Mbps</div></div><div class="col-6"><div class="peak-label">Peak Upload</div><div class="peak-value text-success" id="peakUpload">0 Mbps</div></div></div></div></div><div class="col-lg-4"><div class="monitor-card p-4"><h6 class="mb-3"><i class="bi bi-router"></i> Router Information</h6><div class="info-row"><span class="info-label">Router</span><span class="info-value" id="routerName">-</span></div><div class="info-row"><span class="info-label">Board</span><span class="info-value" id="board">-</span></div><div class="info-row"><span class="info-label">Architecture</span><span class="info-value" id="architecture">-</span></div><div class="info-row"><span class="info-label">RouterOS</span><span class="info-value" id="version">-</span></div></div></div><div class="col-lg-4"><div class="monitor-card p-4"><h6 class="mb-3"><i class="bi bi-clock-history"></i> System Information</h6><div class="info-row"><span class="info-label">Interface</span><span class="info-value">ether1</span></div><div class="info-row"><span class="info-label">Uptime</span><span class="info-value" id="uptime">-</span></div><div class="info-row"><span class="info-label">Last Update</span><span class="info-value" id="lastUpdate">-</span></div></div></div></div></div><script>
const labels=[],downloadData=[],uploadData=[];let peakDownload=0,peakUpload=0;const $=id=>document.getElementById(id);const statusElement=$("status"),downloadElement=$("download"),uploadElement=$("upload"),cpuElement=$("cpu"),memoryElement=$("memory"),diskElement=$("disk"),rxPacketElement=$("rxPacket"),txPacketElement=$("txPacket"),activeAlarmElement=$("activeAlarm"),routerNameElement=$("routerName"),versionElement=$("version"),boardElement=$("board"),architectureElement=$("architecture"),uptimeElement=$("uptime"),lastUpdateElement=$("lastUpdate");const trafficChart=new Chart($("trafficChart").getContext("2d"),{type:"line",data:{labels:labels,datasets:[{label:"Download",data:downloadData,borderColor:"#0d6efd",backgroundColor:"rgba(13,110,253,.12)",borderWidth:3,fill:true,tension:.4,pointRadius:0},{label:"Upload",data:uploadData,borderColor:"#20c997",backgroundColor:"rgba(32,201,151,.10)",borderWidth:3,fill:true,tension:.4,pointRadius:0}]},options:{responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:"index",intersect:false},plugins:{legend:{position:"bottom",labels:{usePointStyle:true,padding:20}},tooltip:{callbacks:{label:c=>c.dataset.label+" : "+Number(c.parsed.y).toFixed(2)+" Mbps"}}},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:10,maxRotation:0}},y:{beginAtZero:true,title:{display:true,text:"Traffic (Mbps)"}}}}});
async function loadData(){try{const r=await fetch("../api/traffic.php?nocache="+Date.now(),{cache:"no-store"});if(!r.ok)throw Error("HTTP "+r.status);const d=await r.json();statusElement.innerHTML=d.status==="online"?'<span class="status-dot"></span>ONLINE':'<span class="status-dot status-offline"></span>OFFLINE';const down=Number(d.download)||0,up=Number(d.upload)||0;downloadElement.textContent=down.toFixed(2)+" Mbps";uploadElement.textContent=up.toFixed(2)+" Mbps";cpuElement.textContent=(Number(d.cpu)||0).toFixed(0)+" %";memoryElement.textContent=(Number(d.memory)||0).toFixed(1)+" %";diskElement.textContent=(Number(d.disk)||0).toFixed(1)+" %";rxPacketElement.textContent=(Number(d.rx_packet)||0).toLocaleString()+" pkt/s";txPacketElement.textContent=(Number(d.tx_packet)||0).toLocaleString()+" pkt/s";routerNameElement.textContent=d.router||"-";versionElement.textContent=d.version||"-";boardElement.textContent=d.board||"-";architectureElement.textContent=d.architecture||"-";uptimeElement.textContent=d.uptime||"-";const now=new Date();lastUpdateElement.textContent=now.toLocaleTimeString();peakDownload=Math.max(peakDownload,down);peakUpload=Math.max(peakUpload,up);$("peakDownload").textContent=peakDownload.toFixed(2)+" Mbps";$("peakUpload").textContent=peakUpload.toFixed(2)+" Mbps";labels.push(now.toLocaleTimeString());downloadData.push(down);uploadData.push(up);if(labels.length>60){labels.shift();downloadData.shift();uploadData.shift()}trafficChart.update("none")}catch(e){console.error(e);statusElement.innerHTML='<span class="status-dot status-offline"></span>OFFLINE'}}
async function loadActiveAlarm(){try{const r=await fetch("../api/alarm_status.php?nocache="+Date.now(),{cache:"no-store"});if(!r.ok)throw Error("Alarm HTTP "+r.status);const d=await r.json();if(d.success&&activeAlarmElement){const total=Number(d.active??d.active_alarm??0);activeAlarmElement.textContent=total;activeAlarmElement.classList.toggle("text-danger",total>0);activeAlarmElement.classList.toggle("text-success",total===0)}}catch(e){console.error("Active Alarm Error",e)}}
let refreshInterval=10000;async function loadSettings(){try{const r=await fetch("../api/settings.php?nocache="+Date.now(),{cache:"no-store"});if(!r.ok)throw Error("Settings HTTP "+r.status);const s=await r.json();if(s.success&&Number(s.refresh_interval)>=10000)refreshInterval=Number(s.refresh_interval)}catch(e){console.error(e);refreshInterval=10000}}
async function refreshDashboard(){await Promise.all([loadData(),loadActiveAlarm()]);setTimeout(refreshDashboard,refreshInterval)}async function startDashboard(){await loadSettings();refreshDashboard()}startDashboard();
</script><script src="../assets/js/dashboard_alarm_widget.js?v=1"></script><script src="../assets/js/alarm_notification.js?v=3"></script><script src="../assets/js/app.js?v=1"></script></body></html>